mapper.select:
select c.site_code, c.chat_id, c.name, c.status, c.last_seen_at, c.update_time
  from monitor_lark_chat c
 where c.chat_id = #{chatId}

mapper.update:
update monitor_lark_chat
   set status = 'dead', update_time = #{now}
 where site_code = #{scope.siteCode}
   and status = 'ok'
   and (last_seen_at is null or last_seen_at < #{now})

update monitor_lark_chat
   set status = 'dead', update_time = #{now}
 where site_code = #{scope.siteCode} and chat_id = #{chatId} and status = 'ok'
